//! 📦️ Declared buffers, views and accessors retain source metadata independently from resolved bytes.
use super::*;
const VALUE:&[FloatColumn]=&[FloatColumn::Binary64(3)];
fn bound(write:&mut Write<'_,'_>,table:&'static str,components:&'static str,key:i64,value:&Option<Vec<f64>>)->Result<(), ValueError>{if let Some(values)=value{write.check(values.len())?;write.insert_key(table,key,&[])?;for(position,value)in values.iter().enumerate(){write.floats(components,&[Cell::Integer(key),ordinal(position)?,Cell::Real(*value)],VALUE)?;}}Ok(())}
fn read_bound(read:&mut Read<'_,'_,'_>,table:&'static str,components:&'static str,key:i64)->Result<Option<Vec<f64>>, ValueError>{if read.optional_key(table,key)?.is_none(){return Ok(None)}let rows=read.rows(components,1,key,2)?;let mut values=Vec::with_capacity(rows.len());for row in rows{read.scalar()?;values.push(FloatRow::new(row,VALUE)?.real(3)?);}Ok(Some(values))}
fn component(read:&mut Read<'_,'_,'_>,row:&SqliteRow,column:usize)->Result<GltfComponentType, ValueError>{read.scalar()?;GltfComponentType::from_code(u64::try_from(row.integer(column)?).map_err(|error| ValueError::new(ValueRefusalKind::InvalidValue, error.to_string()))?).map_err(|error| ValueError::new(ValueRefusalKind::InvalidValue, error))}
pub(super) fn project(write:&mut Write<'_,'_>,document:&GltfDocument)->Result<(), ValueError>{
 write.check(document.buffers.len())?;for(position,buffer)in document.buffers.iter().enumerate(){let [high,low]=index(buffer.byte_length);let [extension,extra]=write.extras(&buffer.extensions,&buffer.extras)?;write.insert("gltf_buffer",&[Cell::Integer(1),ordinal(position)?,high,low,text(&buffer.uri),text(&buffer.name),extension,extra])?;}
 write.check(document.buffer_views.len())?;for(position,view)in document.buffer_views.iter().enumerate(){let [buffer_high,buffer_low]=index(view.buffer);let [offset_high,offset_low]=index(view.byte_offset);let [length_high,length_low]=index(view.byte_length);let [stride_high,stride_low]=optional_index(view.byte_stride);let [target_high,target_low]=optional_word(view.target);let [extension,extra]=write.extras(&view.extensions,&view.extras)?;write.insert("gltf_buffer_view",&[Cell::Integer(1),ordinal(position)?,buffer_high,buffer_low,offset_high,offset_low,length_high,length_low,stride_high,stride_low,target_high,target_low,text(&view.name),extension,extra])?;}
 write.check(document.accessors.len())?;for(position,accessor)in document.accessors.iter().enumerate(){let [view_high,view_low]=optional_index(accessor.buffer_view);let [offset_high,offset_low]=index(accessor.byte_offset);let [count_high,count_low]=index(accessor.count);let [extension,extra]=write.extras(&accessor.extensions,&accessor.extras)?;let key=write.insert("gltf_accessor",&[Cell::Integer(1),ordinal(position)?,view_high,view_low,offset_high,offset_low,Cell::Integer(accessor.component_type.code() as i64),Cell::Integer(i64::from(accessor.normalized)),count_high,count_low,Cell::Text(accessor.kind.as_str()),text(&accessor.name),extension,extra])?;
  bound(write,"gltf_accessor_max","gltf_accessor_max_component",key,&accessor.max)?;bound(write,"gltf_accessor_min","gltf_accessor_min_component",key,&accessor.min)?;
  if let Some(sparse)=&accessor.sparse{let [high,low]=index(sparse.count);write.insert_key("gltf_sparse_accessor",key,&[high,low])?;let [view_high,view_low]=index(sparse.indices.buffer_view);let [offset_high,offset_low]=index(sparse.indices.byte_offset);write.insert_key("gltf_sparse_indices",key,&[view_high,view_low,offset_high,offset_low,Cell::Integer(sparse.indices.component_type.code() as i64)])?;let [view_high,view_low]=index(sparse.values.buffer_view);let [offset_high,offset_low]=index(sparse.values.byte_offset);write.insert_key("gltf_sparse_values",key,&[view_high,view_low,offset_high,offset_low])?;}
 }Ok(())
}
pub(super) fn reconstruct(read:&mut Read<'_,'_,'_>,document:&mut GltfDocument)->Result<(), ValueError>{
 let rows=read.rows("gltf_buffer",1,1,2)?;document.buffers.reserve(rows.len());for row in rows{let extensions=read.json_owned(row,7)?;let extras=read.json_owned(row,8)?;document.buffers.push(GltfBuffer{byte_length:read.index(row,3)?,uri:read.optional_text(row,5)?,name:read.optional_text(row,6)?,extensions:extensions.take(),extras:extras.take()});}
 let rows=read.rows("gltf_buffer_view",1,1,2)?;document.buffer_views.reserve(rows.len());for row in rows{let extensions=read.json_owned(row,14)?;let extras=read.json_owned(row,15)?;document.buffer_views.push(GltfBufferView{buffer:read.index(row,3)?,byte_offset:read.index(row,5)?,byte_length:read.index(row,7)?,byte_stride:read.optional_index(row,9)?,target:read.optional_word(row,11)?,name:read.optional_text(row,13)?,extensions:extensions.take(),extras:extras.take()});}
 let rows=read.rows("gltf_accessor",1,1,2)?;document.accessors.reserve(rows.len());for row in rows{let key=row.rowid;let buffer_view=read.optional_index(row,3)?;let byte_offset=read.index(row,5)?;let component_type=component(read,row,7)?;let normalized=read.boolean(row,8)?;let count=read.index(row,9)?;let kind=row.text(11)?.parse::<GltfAccessorType>().map_err(|message|ValueError::new(ValueRefusalKind::InvalidValue,message))?;let name=read.optional_text(row,12)?;let extensions=read.json_owned(row,13)?;let extras=read.json_owned(row,14)?;let max=read_bound(read,"gltf_accessor_max","gltf_accessor_max_component",key)?;let min=read_bound(read,"gltf_accessor_min","gltf_accessor_min_component",key)?;
  let sparse=if let Some(row)=read.optional_key("gltf_sparse_accessor",key)?{let count=read.index(row,1)?;let row=read.key("gltf_sparse_indices",key)?;let indices=GltfSparseIndices{buffer_view:read.index(row,1)?,byte_offset:read.index(row,3)?,component_type:component(read,row,5)?};let row=read.key("gltf_sparse_values",key)?;let values=GltfSparseValues{buffer_view:read.index(row,1)?,byte_offset:read.index(row,3)?};Some(GltfSparseAccessor{count,indices,values})}else{None};
  document.accessors.push(GltfAccessor{buffer_view,byte_offset,component_type,normalized,count,kind,max,min,sparse,name,extensions:extensions.take(),extras:extras.take()});
 }Ok(())
}
